/**
 * Design tokens: the single source of truth for color, type, spacing, radius, depth, and motion.
 *
 * CSS reads them as custom properties (generated by `tokensToCss` and inlined in <head>).
 * Scripts and, later, the 3D scenes import the same values from this file,
 * so a change here updates the whole site.
 *
 * Contrast ratios are WCAG 2.x, measured against `bg` unless noted.
 */

export const color = {
  // Dark base
  bg: '#0C1210',
  surface: '#15201C', // cards, panels
  raised: '#1C2924', // hovered cards, inputs
  line: '#24332D', // decorative dividers only (not for UI boundaries)
  field: '#66776F', // input borders: 3.5:1 on surface
  text: '#F1F4EF', // 17.1:1
  muted: '#A0AFA8', // 8.3:1, 7.3:1 on surface
  // Accents
  accent: '#FFC229', // marigold: "booked", every primary button. 11.7:1
  accentHover: '#FFD25E',
  accentPress: '#E9A912',
  onAccent: '#0C1210', // text on marigold: 11.7:1
  secondary: '#8BE3BF', // mint: "open / available", focus ring. 12.5:1
  secondaryDim: '#2B4A3E', // mint-tinted fill for open slots
  error: '#FF9F8F', // 8.5:1 on surface
  // Light "paper" chapter
  paper: '#E8EEE8',
  paperSurface: '#F6F9F5',
  ink: '#0C1210', // on paper: 15.6:1
  inkMuted: '#41514A', // on paper: 7.4:1
  paperLine: '#C4D0C7',
  // On paper, the focus ring switches to ink: mint is only 1.3:1 there.
} as const;

export const font = {
  display: 'var(--font-display)',
  body: 'var(--font-body)',
} as const;

/** Fluid type scale. Display sizes run from ~44px on a 360px phone to ~144px on wide screens. */
export const text = {
  displayXl: 'clamp(2.625rem, 1.4rem + 5.2vw, 6.75rem)',
  displayL: 'clamp(2.25rem, 1.2rem + 4.4vw, 5.75rem)',
  displayM: 'clamp(1.75rem, 1.15rem + 2.5vw, 3.25rem)',
  h3: 'clamp(1.25rem, 1.05rem + 0.8vw, 1.625rem)',
  bodyL: 'clamp(1.125rem, 1.03rem + 0.4vw, 1.3125rem)',
  body: 'clamp(1.0625rem, 1.02rem + 0.18vw, 1.1875rem)',
  small: '0.9375rem',
  micro: '0.8125rem',
} as const;

export const leading = { tight: '0.95', snug: '1.15', body: '1.6' } as const;

/** 4px base. */
export const space = {
  1: '0.25rem',
  2: '0.5rem',
  3: '0.75rem',
  4: '1rem',
  5: '1.25rem',
  6: '1.5rem',
  8: '2rem',
  10: '2.5rem',
  12: '3rem',
  16: '4rem',
  20: '5rem',
  gutter: 'clamp(1rem, 0.6rem + 2.4vw, 3rem)',
  section: 'clamp(5rem, 3.5rem + 7vw, 11rem)',
} as const;

/** One tile radius used everywhere: cards, buttons, inputs, and the 3D tiles. */
export const radius = {
  tile: '0.875rem',
  small: '0.5rem',
  large: '1.5rem',
  pill: '999px',
} as const;

export const depth = {
  1: '0 1px 0 rgb(255 255 255 / 0.04) inset, 0 1px 2px rgb(0 0 0 / 0.3)',
  2: '0 1px 0 rgb(255 255 255 / 0.05) inset, 0 8px 24px -8px rgb(0 0 0 / 0.55)',
  3: '0 1px 0 rgb(255 255 255 / 0.06) inset, 0 24px 60px -16px rgb(0 0 0 / 0.7)',
} as const;

/** Damped spring sampled into a CSS linear() easing, so CSS and JS share one spring. */
function springSamples(stiffness = 170, damping = 15, steps = 40): number[] {
  const out: number[] = [];
  const duration = 1; // normalized
  const w0 = Math.sqrt(stiffness);
  const zeta = damping / (2 * Math.sqrt(stiffness));
  const wd = w0 * Math.sqrt(1 - zeta * zeta);
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * duration;
    const v = 1 - Math.exp(-zeta * w0 * t) * (Math.cos(wd * t) + ((zeta * w0) / wd) * Math.sin(wd * t));
    out.push(Math.round(v * 1000) / 1000);
  }
  out[out.length - 1] = 1;
  return out;
}

export const springPoints = springSamples();

export const motion = {
  ease: {
    out: 'cubic-bezier(0.16, 1, 0.3, 1)',
    inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
    spring: `linear(${springPoints.join(', ')})`,
  },
  /** Milliseconds. */
  duration: { press: 120, ui: 240, reveal: 480, chapter: 900 },
  /** Distance a revealed element travels. */
  revealDistance: '1.5rem',
  /** Delay between items in a staggered group. */
  stagger: 60,
} as const;

export const layout = {
  maxWidth: '84rem',
  readable: '38rem',
  headerHeight: '4.5rem',
  mobileCtaHeight: '4.75rem',
} as const;

const kebab = (s: string) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();

/** Turns the tokens into one `:root { ... }` block of CSS custom properties. */
export function tokensToCss(): string {
  const vars: string[] = [];
  const add = (prefix: string, obj: Record<string, string | number>, unit = '') => {
    for (const [k, v] of Object.entries(obj)) vars.push(`--${prefix}-${kebab(k)}: ${v}${unit};`);
  };
  add('c', color);
  add('fs', text);
  add('lh', leading);
  add('sp', space);
  add('r', radius);
  add('depth', depth);
  add('ease', motion.ease);
  add('dur', motion.duration, 'ms');
  add('layout', layout);
  vars.push(`--reveal-distance: ${motion.revealDistance};`);
  vars.push(`--stagger: ${motion.stagger}ms;`);
  return `:root{${vars.join('')}}`;
}
